use super::consts::SUPPORTED_AUDIO_EXTENSIONS;
use std::path::Path;

pub fn is_supported_audio_extension(ext: &str) -> bool {
    SUPPORTED_AUDIO_EXTENSIONS
        .iter()
        .any(|supported| supported.eq_ignore_ascii_case(ext))
}

pub(super) fn is_supported_audio_path(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .is_some_and(is_supported_audio_extension)
}

/// Check if a file is an image based on extension
pub(super) fn is_image_file(path: &Path) -> bool {
    if let Some(ext) = path.extension() {
        let ext_lower = ext.to_string_lossy().to_lowercase();
        matches!(ext_lower.as_str(), "jpg" | "jpeg" | "png" | "gif" | "webp")
    } else {
        false
    }
}
